import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const o="/llamatron/assets/chain_editor.iMfBdvkP.svg",u=JSON.parse('{"title":"Chain","description":"","frontmatter":{},"headers":[],"relativePath":"generators/CHAIN.md","filePath":"generators/CHAIN.md"}'),i={name:"generators/CHAIN.md"};function h(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="chain" tabindex="-1">Chain <a class="header-anchor" href="#chain" aria-label="Permalink to &quot;Chain&quot;">​</a></h1><p><img src="'+o+'" alt="The chain editor"></p><p>A Chain is a generator that runs other generators, one after another, as a list. A clip, a scene or a track can list generators of its own, so a Chain is for a list that several of them share: a pedalboard of effects that a guitarist carries from song to song, set up once and switched on wherever it is wanted. Change the Chain, and every clip that runs it hears the change.</p><h2 id="how-a-chain-runs" tabindex="-1">How a Chain Runs <a class="header-anchor" href="#how-a-chain-runs" aria-label="Permalink to &quot;How a Chain Runs&quot;">​</a></h2><p>A Chain runs its generators from top to bottom, each working on what the generator before it made. An arpeggiator followed by an AutoRatchet arpeggiates first and then chops every arpeggiated note into repeats, while an AutoRatchet followed by an arpeggiator ratchets the chords first and then arpeggiates the repeats.</p><p>Listed on a clip, a scene or a track, a Chain runs its generators in its own place in that list. A clip whose Generators field holds a Guitarify, then a Chain of an arpeggiator and an AutoRatchet, then a Swell, plays as if its list were the Guitarify, the arpeggiator, the AutoRatchet and the Swell. A Chain&#39;s own steps are plain generators, never another Chain.</p><h2 id="placement" tabindex="-1">Placement <a class="header-anchor" href="#placement" aria-label="Permalink to &quot;Placement&quot;">​</a></h2><p>A clip runs its own generators first, then its scene&#39;s, then its track&#39;s, and a generator, a Chain among them, listed twice runs twice. The clip page, the Scene page and the track editor each have a Generators field that opens the list, where a Chain sits beside any other generator.</p><h2 id="chain-editor" tabindex="-1">Chain Editor <a class="header-anchor" href="#chain-editor" aria-label="Permalink to &quot;Chain Editor&quot;">​</a></h2><p>Make a Chain on the Generators page with <code>A</code>, choosing Chain under the Chains heading; <code>ENTER</code> on it opens the chain editor.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>A</code></td><td>Add a step: any generator but a Chain, made first on the Generators page</td></tr><tr><td><code>ENTER</code></td><td>Change the step to another generator</td></tr><tr><td><code>C</code></td><td>Copy the step</td></tr><tr><td><code>W</code></td><td>Open the Chain&#39;s Bypass Generators When statements, which say when a pass goes by the whole Chain. See <a href="./../REGISTERS#conditional-execution">Conditional Execution</a></td></tr><tr><td><code>M</code></td><td>Pick it up: <code>↑↓</code> carry it, and <code>ENTER</code> drops it</td></tr><tr><td><code>Bksp</code></td><td>Remove it</td></tr><tr><td><code>N</code></td><td>Rename the Chain, which updates every list that runs it</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p><code>examples/learning/17_complex_gifts_chain.yml</code> runs Chains of arpeggiators and AutoRatchets on Simple Gifts.</p>',13)])])}const f=t(i,[["render",h]]);export{u as __pageData,f as default};
